<!doctype html>
<html><head><meta charset="utf-8"><style>
body{font-family:DejaVu Sans,sans-serif;color:#172033;font-size:12px;margin:34px}.header{border-bottom:3px solid #2563eb;padding-bottom:18px;margin-bottom:24px}.brand{font-size:25px;font-weight:700}.muted{color:#64748b}.right{text-align:right}.grid{width:100%;border-collapse:collapse}.grid td{vertical-align:top}.box{border:1px solid #cbd5e1;padding:14px;margin:18px 0}.items{width:100%;border-collapse:collapse;margin-top:24px}.items th{background:#eff6ff;text-align:left;padding:10px;border-bottom:1px solid #bfdbfe}.items td{padding:11px 10px;border-bottom:1px solid #e2e8f0}.totals{width:46%;margin-left:auto;margin-top:18px;border-collapse:collapse}.totals td{padding:7px}.grand{font-size:16px;font-weight:700;border-top:2px solid #2563eb}.footer{margin-top:50px;border-top:1px solid #e2e8f0;padding-top:12px;color:#64748b;font-size:10px}
