<div class="header"><table class="grid"><tr><td><div class="brand">SimplyHiree</div><div class="muted">Recruitment Services Invoice</div></td><td class="right"><b>INVOICE</b><br>SH-INV-{{ str_pad((string)$application->id,6,'0',STR_PAD_LEFT) }}<br><span class="muted">{{ optional($application->invoice_generated_at ?? now())->format('d M Y') }}</span></td></tr></table></div>
<table class="grid"><tr><td width="55%"><b>Bill To</b><div class="box">{{ $application->job?->user?->clientProfile?->company_name ?? $application->job?->user?->name }}<br>{{ $application->job?->user?->email }}<br>{{ $application->job?->user?->clientProfile?->address }}<br>@if($application->job?->user?->clientProfile?->gst_number)GSTIN: {{ $application->job->user->clientProfile->gst_number }}@endif</div></td><td width="5%"></td><td><b>Placement</b><div class="box">Candidate: {{ $invoice['candidate_name'] }}<br>Role: {{ $invoice['job_title'] }}<br>Joining: {{ $invoice['joining_date']?->format('d M Y') }}<br>Final CTC: ₹{{ number_format((float)$invoice['final_ctc'],2) }}</div></td></tr></table>
<table class="items"><thead><tr><th>Description</th><th class="right">Amount</th></tr></thead><tbody><tr><td>Recruitment service fee — {{ str_replace('_',' ',(string)$invoice['billing_type']) }}</td><td class="right">₹{{ number_format((float)$invoice['invoice_amount'],2) }}</td></tr></tbody></table>
